const calendarSourceId = $('Loop_Calendars').item.json.id;
const items = $input.all();

const toNaive = (iso) => {
  if (!iso) return null;
  // Strip timezone: keep wall-clock time as YYYY-MM-DD HH:MM:SS
  return iso.substring(0, 19).replace('T', ' ');
};

const mapStatus = (s) => {
  if (s === 'cancelled') return 'canceled';
  if (s === 'tentative') return 'tentative';
  return 'scheduled';
};

const valid = items
  .filter((it) => it.json && it.json.id && it.json.status !== 'cancelled')
  .map((it) => {
    const ev = it.json;
    const startIso = (ev.start && ev.start.dateTime)
      ? ev.start.dateTime
      : (ev.start && ev.start.date ? ev.start.date + 'T00:00:00' : null);
    const endIso = (ev.end && ev.end.dateTime)
      ? ev.end.dateTime
      : (ev.end && ev.end.date ? ev.end.date + 'T00:00:00' : null);

    return {
      json: {
        calendar_source_id: calendarSourceId,
        google_event_id: ev.id,
        summary: ev.summary || '(Sin título)',
        status: mapStatus(ev.status),
        start_datetime: toNaive(startIso),
        end_datetime: toNaive(endIso),
        color: ev.colorId || null,
        notes: ev.description || null,
      },
    };
  })
  .filter((it) => it.json.start_datetime && it.json.end_datetime);

// Always emit at least one item so the loop continues even when a calendar
// has no events. The Insert query skips items with null google_event_id.
if (valid.length === 0) {
  return [{ json: { calendar_source_id: calendarSourceId, google_event_id: null, summary: null, status: null, start_datetime: null, end_datetime: null, color: null, notes: null } }];
}

return valid;

// Insertar si falta devuelve una fila por cita creada (RETURNING) y un
// {success:true} cuando no inserta nada; solo cuentan las filas con id.
const inserted = $input.all().filter((it) => it.json && it.json.id != null);
const calendars = $('Calendarios activos').all();

const byCalendar = calendars.map((c) => ({
  calendar_source_id: c.json.id,
  calendario: c.json.name,
  importadas: inserted.filter((it) => String(it.json.calendar_source_id) === String(c.json.id)).length,
}));

return [{ json: { total_importadas: inserted.length, por_calendario: byCalendar } }];
